operation.add:
if (!isset($this->session->data['payment_address'])) {
				if ($this->customer->isLogged() && $this->customer->getAddressId()) {
					$this->load->model('account/address');
					$addr = $this->model_account_address->getAddress($this->customer->getAddressId());
					if ($addr) {
						$this->session->data['payment_address'] = $addr;
					}
				}
				if (empty($this->session->data['payment_address'])) {
					$this->session->data['payment_address'] = array(
						'firstname'      => '',
						'lastname'       => '',
						'company'        => '',
						'address_1'      => '',
						'address_2'      => '',
						'city'           => '',
						'postcode'       => '',
						'zone'           => '',
						'zone_id'        => (int)$this->config->get('config_zone_id'),
						'country'        => '',
						'country_id'     => (int)$this->config->get('config_country_id'),
						'address_format' => '',
						'custom_field'   => array(),
					);
				}
			}
